import React from 'react';
import {
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  Stack,
  Typography,
} from '@mui/material';
import { Gavel as GavelIcon } from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import type { FrameworkDataGap } from '../../utils/sustainabilityUx';
import useAppTranslation from '../../hooks/useAppTranslation';

export interface DashboardFrameworkGapsCardProps {
  gaps: FrameworkDataGap[];
}

export const DashboardFrameworkGapsCard: React.FC<DashboardFrameworkGapsCardProps> = ({ gaps }) => {
  const navigate = useNavigate();
  const { t } = useAppTranslation();

  if (gaps.length === 0) {
    return null;
  }

  return (
    <Card variant="outlined" sx={{ mb: 3, borderColor: 'warning.light' }}>
      <CardContent>
        <Stack direction="row" spacing={1.5} alignItems="flex-start" sx={{ mb: 2 }}>
          <GavelIcon color="warning" sx={{ mt: 0.25 }} />
          <Box sx={{ flex: 1, minWidth: 0 }}>
            <Typography variant="overline" color="warning.dark" sx={{ fontWeight: 700, letterSpacing: '0.08em' }}>
              {t('dashboard.frameworkGapsTitle')}
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ lineHeight: 1.55 }}>
              Gaps that may block BRSR, export, or buyer audit submissions until resolved.
            </Typography>
          </Box>
        </Stack>
        <Stack spacing={1.5}>
          {gaps.map((gap) => (
            <Box
              key={`${gap.framework}-${gap.actionPath}`}
              sx={{
                display: 'flex',
                flexDirection: { xs: 'column', sm: 'row' },
                alignItems: { xs: 'flex-start', sm: 'center' },
                justifyContent: 'space-between',
                gap: 1,
                p: 1.5,
                borderRadius: 2,
                bgcolor: (theme) =>
                  theme.palette.mode === 'dark' ? 'rgba(255, 152, 0, 0.08)' : 'rgba(255, 152, 0, 0.06)',
              }}
            >
              <Box sx={{ flex: 1, minWidth: 0 }}>
                <Chip size="small" label={gap.framework} variant="outlined" sx={{ mb: 0.75 }} />
                <Typography variant="body2" sx={{ lineHeight: 1.5 }}>
                  {gap.gap}
                </Typography>
              </Box>
              <Button size="small" variant="outlined" onClick={() => navigate(gap.actionPath)}>
                {gap.actionLabel}
              </Button>
            </Box>
          ))}
        </Stack>
      </CardContent>
    </Card>
  );
};

export default DashboardFrameworkGapsCard;
