import React from 'react';
import { Box, Typography } from '@mui/material';

interface DashboardSectionHeadingProps {
  title: string;
  subtitle?: string;
}

export const DashboardSectionHeading: React.FC<DashboardSectionHeadingProps> = ({ title, subtitle }) => (
  <Box sx={{ mb: 2 }}>
    <Typography
      variant="overline"
      sx={{
        display: 'block',
        fontWeight: 700,
        letterSpacing: '0.12em',
        color: 'primary.main',
        lineHeight: 1.2,
      }}
    >
      {title}
    </Typography>
    {subtitle ? (
      <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5, maxWidth: 720 }}>
        {subtitle}
      </Typography>
    ) : null}
  </Box>
);
